data class FeedUiState(val items: List<PostUi> = emptyList(), val loading: Boolean = false, val error: String? = null)
sealed interface FeedAction { data object Refresh : FeedAction; data class Open(val id: String) : FeedAction }
class FeedViewModel(private val refreshFeed: RefreshFeed) : ViewModel() {
 private val _state = MutableStateFlow(FeedUiState())
 val state: StateFlow<FeedUiState> = _state.asStateFlow()
 fun onAction(a: FeedAction) { if (a is FeedAction.Refresh) refresh() }
 private fun refresh() = viewModelScope.launch {
  _state.update { it.copy(loading = true, error = null) }
  runCatching { refreshFeed() }.onFailure { e -> _state.update { it.copy(error = e.message) } }
  _state.update { it.copy(loading = false) }
 }
}

@Composable fun FeedRoute(vm: FeedViewModel, onOpen: (String) -> Unit) {
 val state by vm.state.collectAsStateWithLifecycle()
 FeedScreen(state = state, onRefresh = { vm.onAction(FeedAction.Refresh) }, onOpen = onOpen)
}

class PostViewModel(savedStateHandle: SavedStateHandle, observePost: ObservePost) : ViewModel() {
 private val postId: String = requireNotNull(savedStateHandle["postId"])
 val state = observePost(postId).map(::toUiState).stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), PostUiState.Loading)
}
